package com.rork.rockscout.data

/** A U.S. state park with rockhounding or geological relevance. */
data class StatePark(
    val id: String,            // unique slug
    val name: String,
    val state: String,         // state code, e.g. "AZ"
    val region: String,        // "Tucson, Arizona"
    val description: String,
    val latitude: Double,
    val longitude: Double,
    val hasCamping: Boolean,
    val feeInfo: String,
    val website: String?,
)

